import { motogpFetch } from "./motogpApi";

import type {
MotoGPEvent,
EventsResponse,
} from "@/types/grandPrix";

export async function getEventsBySeason(
seasonId: string
): Promise<MotoGPEvent[]> {

const endpoint =
`/results/events?seasonUuid=${seasonId}`;

return motogpFetch<EventsResponse>(
endpoint
);
}

export async function getCurrentGrandPrix(
seasonId: string
): Promise<MotoGPEvent | null> {

const events =
await getEventsBySeason(seasonId);

const currentEvent =
events.find(
(event) =>
event.status === "CURRENT"
);

return currentEvent || null;
}
